#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<char> isPrime(n + 1, 1);
    isPrime[0] = 0;
    if (n >= 1) isPrime[1] = 0;
    for (long long p = 2; p * p <= n; p++) {
        if (isPrime[p]) {
            for (long long j = p * p; j <= n; j += p) isPrime[j] = 0;
        }
    }
    int count = 0;
    for (int i = 2; i <= n; i++) count += isPrime[i];
    cout << count << endl;
    return 0;
}
